                    "sql": "Create or replace table snitch_db.maplemonk.final_puv_verification as SELECT _AIRBYTE_DATA:_ab_additional_properties:\"SKU\"::string AS \"BARCODE\", _AIRBYTE_DATA:\"BILL DATE\"::string AS \"BILL DATE\", _AIRBYTE_DATA:\"BILL NO.\"::string AS \"BILL NO.\", _AIRBYTE_DATA:\"BRANCH NAME\"::string AS \"BRANCH NAME\", _AIRBYTE_DATA:\"CATEGORY\"::string AS \"CATEGORY\", _AIRBYTE_DATA:\"CD VALUE\"::string AS \"CD VALUE\", _AIRBYTE_DATA:\"CD(%)\"::string AS \"CD(%)\", _AIRBYTE_DATA:\"CGST\"::string AS \"CGST\", _AIRBYTE_DATA:\"COMPANY NAME\"::string AS \"COMPANY NAME\", _AIRBYTE_DATA:\"FIT\"::string AS \"FIT\", _AIRBYTE_DATA:\"GRN NO.\"::string AS \"GRN NO.\", _AIRBYTE_DATA:\"GROSS VALUE\"::string AS \"GROSS VALUE\", _AIRBYTE_DATA:\"HSN GROUP\"::string AS \"HSN GROUP\", _AIRBYTE_DATA:\"ITEM CODE\"::string AS \"ITEM CODE\", _AIRBYTE_DATA:\"ITEM NAME\"::string AS \"ITEM NAME\", _AIRBYTE_DATA:\"NET AMOUNT\"::string AS \"NET AMOUNT\", _AIRBYTE_DATA:\"PO ORDER DATE\"::string AS \"PO ORDER DATE\", _AIRBYTE_DATA:\"PO ORDER NO.\"::string AS \"PO ORDER NO.\", _AIRBYTE_DATA:\"PRODUCT\"::string AS \"PRODUCT\", SPLIT_PART(_AIRBYTE_DATA:\"PUR QTY\", \',\', 1)::int AS \"PUR QTY\", _AIRBYTE_DATA:\"RATE\"::string AS \"RATE\", _AIRBYTE_DATA:\"RECEIPT DATE\"::string AS \"RECEIPT DATE\", _AIRBYTE_DATA:\"ROUND AMOUNT\"::string AS \"ROUND AMOUNT\", _AIRBYTE_DATA:\"SGST/IGST\"::string AS \"SGST/IGST\", _AIRBYTE_DATA:\"SIZE\"::string AS \"SIZE\", _AIRBYTE_DATA:\"SNO.\"::string AS \"SNO.\", _AIRBYTE_DATA:\"SUPPLIER NAME\"::string AS \"SUPPLIER NAME\", _AIRBYTE_DATA:\"TAX REGION\"::string AS \"TAX REGION\", _AIRBYTE_DATA:\"TAX-2(%)\"::string AS \"TAX-2(%)\", _AIRBYTE_DATA:\"TAX-2(RS)\"::string AS \"TAX-2(RS)\", _AIRBYTE_DATA:\"TAXABLE AMOUNT\"::string AS \"TAXABLE AMOUNT\", _AIRBYTE_DATA:\"GOODS IN TRANSIT\"::string AS \"GOODS IN TRANSIT\", _AIRBYTE_DATA:\"_ab_additional_properties\"::string AS \"_ab_additional_properties\", _AIRBYTE_DATA:\"_ab_source_file_last_modified\"::string AS \"_ab_source_file_last_modified\", _AIRBYTE_DATA:\"_ab_source_file_url\"::string AS \"_ab_source_file_url\" FROM snitch_db.maplemonk._AIRBYTE_RAW_puv_verification where _AIRBYTE_DATA:\"PRODUCT\"::string not in (\'CARRY BAG\',\'NON- TRADING\',\'BIN\') ; CREATE or REPLACE TABLE SNITCH_DB.MAPLEMONK.JIT_OFFLINE_GOODS AS Select * from ( With final as (Select * from ( Select * from ( With overall as ( Select CASE WHEN POSITION(\'-\' IN \"BARCODE\") > 0 AND LEFT(\"BARCODE\", 2) = \'4C\' THEN SPLIT_PART(\"BARCODE\", \'-\', 1) || \'-\' || SPLIT_PART(\"BARCODE\", \'-\', 2) || \'-\' || SPLIT_PART(\"BARCODE\", \'-\', 3) WHEN POSITION(\'-\' IN \"BARCODE\") > 0 AND LEFT(\"BARCODE\", 2) = \'SH\' THEN SPLIT_PART(\"BARCODE\", \'-\', 1) WHEN POSITION(\'-\' IN \"BARCODE\") > 0 THEN SPLIT_PART(\"BARCODE\", \'-\', 1) || \'-\' || SPLIT_PART(\"BARCODE\", \'-\', 2) ELSE \"BARCODE\" END AS sku_group , \"BARCODE\" AS \"ITEM CODE\", branch_code_priority , \"BRANCH NAME\", CASE WHEN \"RECEIPT DATE\" LIKE \'%/%/%\' THEN TO_DATE(\"RECEIPT DATE\", \'DD/MM/YYYY\') WHEN \"RECEIPT DATE\" LIKE \'%-%-%\' THEN TO_DATE(\"RECEIPT DATE\", \'DD-MM-YYYY\') ELSE NULL END AS Inward_date, SUM(\"PUR QTY\") AS qty, \'PUV Verification Pending\' as Status, DATEDIFF( DAY, inward_date, CURRENT_DATE ) AS aging from ( SELECT a.*, b.branch_code_priority FROM snitch_db.maplemonk.final_puv_verification a left join ( SELECT DISTINCT e.\"BRANCH NAME\", s.branch_code_priority FROM snitch_db.maplemonk.final_puv_verification e LEFT JOIN snitch_db.maplemonk.storepriority s ON e.\"BRANCH NAME\" LIKE \'%\' || s.branch_name_priority || \'%\') b on a.\"BRANCH NAME\" =b.\"BRANCH NAME\" where lower(\"GOODS IN TRANSIT\") = \'true\') GROUP BY 1,2,3,4,5 Union ALL Select CASE WHEN POSITION(\'-\' IN \"SKU\") > 0 AND LEFT(\"SKU\", 2) = \'4C\' THEN SPLIT_PART(\"SKU\", \'-\', 1) || \'-\' || SPLIT_PART(\"SKU\", \'-\', 2) || \'-\' || SPLIT_PART(\"SKU\", \'-\', 3) WHEN POSITION(\'-\' IN \"SKU\") > 0 AND LEFT(\"SKU\", 2) = \'SH\' THEN SPLIT_PART(\"SKU\", \'-\', 1) WHEN POSITION(\'-\' IN \"SKU\") > 0 THEN SPLIT_PART(\"SKU\", \'-\', 1) || \'-\' || SPLIT_PART(\"SKU\", \'-\', 2) ELSE \"SKU\" END as sku_group ,* from ( with git as (select final_store::TEXT as FINAL_STORE, order_date, sku, final_status , sum(qty) as q1 from snitch_db.maplemonk.b2b_journey where final_status not in (\'INWARDED\') group by 1,2,3,4 ), branch as (select store_name::TEXT as STORE_NAME , store_code from snitch_db.maplemonk.OFFLINE_STORE_DETAILED_MAPPING) select g.sku, b.store_code as branch_code, g.final_store as store, g.order_date ,g.q1 as qty , g.final_status as status, current_date - g.order_date as aging from git g left join branch b on g.final_store::TEXT = b.store_name ) ) , deatilas as ( select * from ( select CASE WHEN POSITION(\'-\' IN sku_group) > 0 AND LEFT(sku_group, 2) = \'SH\' THEN SPLIT_PART(sku_group, \'-\', 1) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END as sku_group, product_name, category, final_ros, natural_ros, sku_class , ROW_NUMBER() OVER (PARTITION BY CASE WHEN POSITION(\'-\' IN sku_group) > 0 AND LEFT(sku_group, 2) = \'SH\' THEN SPLIT_PART(sku_group, \'-\', 1) WHEN POSITION(\'-\' IN sku_group) > 0 THEN SPLIT_PART(sku_group, \'-\', 1) || \'-\' || SPLIT_PART(sku_group, \'-\', 2) ELSE sku_group END ORDER BY 1) AS rn, from snitch_db.maplemonk.availability_master_v2) where rn=1 ) SELECT a.*, b.product_name, b.category, b.final_ros AS online_final_ros, b.natural_ros AS online_natural_ros, b.sku_class FROM overall a LEFT JOIN deatilas b ON a.SKU_GROUP = b.sku_group ) where sku_group not like \'%CB%\' ) ), haa as ( Select * from ( SELECT DISTINCT branch_code, marketplace_mapped, ROW_NUMBER() OVER (PARTITION BY branch_code ORDER BY order_date DESC) AS rn FROM snitch_db.maplemonk.STORE_fact_items_offline) WHERE rn = 1 ) Select a.SKU_GROUP, a.\"ITEM CODE\", a.INWARD_DATE, a.QTY, a.STATUS, a.AGING, a.PRODUCT_NAME, a.CATEGORY, a.ONLINE_FINAL_ROS, a.ONLINE_NATURAL_ROS, a.SKU_CLASS, CASE WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - INFINITY ANDHERI -MUMBAI\' THEN 28 WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - C ROAD -JODHPUR\' THEN 40 WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - METRO MALL -KALYAN\' THEN 42 WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - PALASSIO MALL -LUCKNKW\' THEN 48 WHEN a.\"BRANCH NAME\" = \'SNITCH - COCO - DLF CYBERHUB\' THEN 108 WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - MYSURU\' THEN 97 WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - SINDHUBHAVAN\' THEN 103 WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - POLARIS VIP ROAD\' THEN 109 WHEN a.\"BRANCH NAME\" = \'SNITCH - COCO - MOTI NAGAR\' THEN 106 ELSE COALESCE(b.branch_code, a.branch_code_priority) END AS branch_code, CASE WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - INFINITY ANDHERI -MUMBAI\' THEN \'SNITCH - COFO - INFINITI ANDHERI\' WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - C ROAD -JODHPUR\' THEN \'SNITCH - FOCO - C ROAD JODHPUR\' WHEN a.\"BRANCH NAME\" = \'SNITCH - COFO - METRO MALL -KALYAN\' THEN \'SNITCH - COFO - METRO MALL\' WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - PALASSIO MALL -LUCKNKW\' THEN \'SNITCH - FOCO - PALASSIO MALL\' WHEN a.\"BRANCH NAME\" = \'SNITCH - FOCO - PALASSIO MALL -LUCKNOW\' THEN \'SNITCH - FOCO - PALASSIO MALL\' ELSE COALESCE(b.marketplace_mapped, a.\"BRANCH NAME\") END AS Store from final a left join haa b on a.\"BRANCH NAME\" = b.marketplace_mapped ) ;",
